     9→import com.artipie.docker.RepoName;
    10→import com.artipie.docker.Tag;
    11→import com.artipie.docker.Tags;
    12→import java.util.Collection;
    13→import java.util.Optional;
    14→import java.util.stream.Collectors;
    15→import javax.json.Json;
    16→import javax.json.JsonArrayBuilder;
    17→
    18→/**
    19→ * Asto implementation of {@link Tags}. Tags created from list of keys.
    20→ *
    21→ * @since 0.8
    22→ */
    23→final class AstoTags implements Tags {
    24→
    25→    /**
    26→     * Repository name.
    27→     */
    28→    private final RepoName name;
    29→
    30→    /**
    31→     * Tags root key.
    32→     */
    33→    private final Key root;
    34→
    35→    /**
    36→     * List of keys inside tags root.
    37→     */
    38→    private final Collection<Key> keys;
    39→
    40→    /**
    41→     * From which tag to start, exclusive.
    42→     */
    43→    private final Optional<Tag> from;
    44→
    45→    /**
    46→     * Maximum number of tags returned.
    47→     */
    48→    private final int limit;
    49→
    50→    /**
    51→     * Ctor.
    52→     *
    53→     * @param name Repository name.
    54→     * @param root Tags root key.
    55→     * @param keys List of keys inside tags root.
    56→     * @param from From which tag to start, exclusive.
    57→     * @param limit Maximum number of tags returned.
    58→     * @checkstyle ParameterNumberCheck (2 lines)
    59→     */
    60→    AstoTags(
    61→        final RepoName name,
    62→        final Key root,
    63→        final Collection<Key> keys,
    64→        final Optional<Tag> from,
    65→        final int limit
    66→    ) {
    67→        this.name = name;
    68→        this.root = root;
    69→        this.keys = keys;
    70→        this.from = from;
    71→        this.limit = limit;
    72→    }
    73→
    74→    @Override
    75→    public Content json() {
    76→        final JsonArrayBuilder builder = Json.createArrayBuilder();
    77→        this.tags().stream()
    78→            .map(Tag::value)
    79→            .filter(tag -> this.from.map(last -> tag.compareTo(last.value()) > 0).orElse(true))
    80→            .limit(this.limit)
    81→            .forEach(builder::add);
    82→        return new Content.From(
    83→            Json.createObjectBuilder()
    84→                .add("name", this.name.value())
    85→                .add("tags", builder)
    86→                .build()
    87→                .toString()
    88→                .getBytes()
    89→        );
    90→    }
    91→
    92→    /**
    93→     * Convert keys to ordered set of tags.
    94→     *
    95→     * @return Ordered tags.
    96→     */
    97→    private Collection<Tag> tags() {
    98→        return new Children(this.root, this.keys).names().stream()
    99→            .map(Tag.Valid::new)
